public enum VehicleType
{
    Motorcycle,  // fits in any spot
    Car,         // fits in Car and Truck spots
    Truck        // fits only in Truck spots
}

public class ParkingSpot
{
    public string Id { get; }
    public VehicleType Size { get; }
    public bool IsOccupied { get; private set; }
    public Vehicle? CurrentVehicle { get; private set; }

    public bool CanFit(VehicleType vehicleType)
    {
        return vehicleType switch
        {
            VehicleType.Motorcycle => true,
            VehicleType.Car => Size is VehicleType.Car or VehicleType.Truck,
            VehicleType.Truck => Size == VehicleType.Truck,
            _ => false
        };
    }

    public void Park(Vehicle vehicle)
    {
        if (IsOccupied || !CanFit(vehicle.Type))
            throw new InvalidOperationException("Spot unavailable");
        CurrentVehicle = vehicle;
        IsOccupied = true;
    }

    public void Vacate()
    {
        CurrentVehicle = null;
        IsOccupied = false;
    }
}

public class Ticket
{
    public string Id { get; } = Guid.NewGuid().ToString();
    public string SpotId { get; }
    public VehicleType VehicleType { get; }
    public DateTime EntryTime { get; } = DateTime.UtcNow;
    public DateTime? ExitTime { get; private set; }
    public decimal Fee { get; private set; }

    public void Close(DateTime exitTime, decimal fee)
    {
        ExitTime = exitTime;
        Fee = fee;
    }
}

public class ParkingLot
{
    private readonly List<ParkingSpot> _spots = new();
    private readonly Dictionary<string, Ticket> _activeTickets = new();

    public Ticket ParkVehicle(VehicleType type)
    {
        var spot = _spots.FirstOrDefault(s => !s.IsOccupied && s.CanFit(type))
                   ?? throw new InvalidOperationException("No spot available");
        spot.Park(new Vehicle(type));
        var ticket = new Ticket { SpotId = spot.Id, VehicleType = type };
        _activeTickets[ticket.Id] = ticket;
        return ticket;
    }

    public decimal Exit(string ticketId)
    {
        var ticket = _activeTickets[ticketId];
        var spot = _spots.First(s => s.Id == ticket.SpotId);
        spot.Vacate();
        var fee = CalculateFee(ticket);
        ticket.Close(DateTime.UtcNow, fee);
        _activeTickets.Remove(ticketId);
        return fee;
    }
}
